To create a Discord bot using Discord.js v14 that has a single command called "ban", follow these steps:

1. Create a new project directory and navigate to it in your terminal.
2. Initialize a new Node.js project using `npm init` and follow the prompts to set up the package.json file.
3. Install the necessary dependencies using `npm install discord.js dotenv` or `yarn add discord.js dotenv`.
4. Create a `.env` file in the root of your project directory, and add your Discord bot token to it like this:

```
DISCORD_TOKEN=<your_discord_bot_token_here>
```

5. Create a `index.js` file in the root of your project directory, and add the following code:

```javascript
// Import required modules
const { Client, GatewayIntentBits } = require('discord.js');
const { token } = require('./config'); // Import your Discord bot token from the .env file

// Create a new Discord client instance
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Load the Discord bot commands
client.commands = new Map();
const commandFiles = process.cwd().concat('/commands');

client.handleCommands = () => {
  const commandFolders = fs.readdirSync(commandFiles, { withFileTypes: true });
  for (const folder of commandFolders) {
    if (folder.isDirectory()) {
      const commandFiles = fs.readdirSync(`${commandFiles}/${folder.name}`, { withFileTypes: true });
      for (const file of commandFiles) {
        if (file.isFile() && file.name.endsWith('.js')) {
          const command = require(`./commands/${folder.name}/${file.name}`);
          client.commands.set(command.data.name, command);
        }
      }
    }
  }
};

// Handle the interactionCreate event
client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

// Login the Discord bot with the token
client.login(token);
```

6. Create a `config.js` file in the root of your project directory, and add your Discord bot token to it like this:

```javascript
module.exports = {
  token: process.env.DISCORD_TOKEN,
};
```

7. Create a `commands` folder in the root of your project directory.
8. Create a new file called `ban.js` inside the `commands` folder, and add the following code:

```javascript
const { SlashCommandBuilder } = require('discord.js');

module.exports = {
  data: new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Bans a user from the server.')
    .addUserOption((option) =>
      option
        .setName('user')
        .setDescription('The user to ban.')
        .setRequired(true)
    ),
  async execute(interaction) {
    const user = interaction.options.getUser('user');

    await interaction.guild.members.ban(user);

    await interaction.reply(`User ${user.username} has been banned.`);
  },
};
```

9. Save the files and run your Discord bot using `node index.js` or `npm run start` (if you created an `npm start` script in your `package.json` file).

Now, your Discord bot should be online and responding to the `/ban` command with the provided user as argument. Make sure to test it out with your Discord bot's server!

Here's a possible implementation of the Markdown to HTML conversion function:

```cpp
#include <string>
#include <sstream>
#include <vector>
#include <unordered_map>

// Markdown to HTML conversion rules
const std::unordered_map<std::string, std::string> md2html_rules = {
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"`", "<code>"},
    {"**", "<strong>"},
    {"*", "<em>"},
    {"[", "<a href='"],
    {"(", "<img src='"],
    {"](", ")' alt='"],
    {"](", ")' alt=''"},
    {"|", "<table><tr><td>"},
    {"|", "</td><td>"},
    {"|", "</td></tr></table>"},
    {"---", "<hr>"},
    {"   ", "&nbsp;&nbsp;"}
};

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream html;
    std::vector<std::string> lines;
    std::string line;

    // Split markdown into lines
    for (const auto& c : markdown) {
        if (c == '\n') {
            lines.emplace_back(line);
            line.clear();
        } else {
            line += c;
        }
    }
    if (!line.empty()) {
        lines.emplace_back(line);
    }

    // Convert each line to HTML
    for (const auto& line : lines) {
        std::string html_line;
        std::size_t pos = 0;

        // Apply Markdown to HTML conversion rules
        while ((pos = line.find_first_of(md2html_rules, pos)) != std::string::npos) {
            const auto& rule = md2html_rules.at(line.substr(pos, 2));
            html_line += line.substr(pos, 2);
            html_line += rule;
            pos += 2;
        }

        // Append remaining plain text
        html_line += line.substr(pos);

        // Append converted line to HTML stream
        html << html_line << "\n";
    }

    return html.str();
}
```

This implementation uses an unordered map to store the Markdown to HTML conversion rules, and applies them using a simple pattern matching algorithm.

