Here's a sample C++ program that reads a text file line by line, counts the number of occurrences of a specific word, and displays the count:

```c++
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string filename;
    string word;
    int count = 0;

    // Prompt user for file name and word to count
    cout << "Enter the name of the file: ";
    cin >> filename;
    cout << "Enter the word to count: ";
    cin >> word;

    // Open file for reading
    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error opening file: " << filename << endl;
        return 1;
    }

    // Read file line by line
    string line;
    while (getline(file, line)) {
        // Convert line to lowercase for case-insensitive comparison
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of word in line
        size_t pos = line.find(word);
        while (pos != string::npos) {
            count++;
            pos = line.find(word, pos + 1);
        }
    }

    // Close file
    file.close();

    // Display count
    cout << "Number of occurrences of \"" << word << "\" in " << filename << ": " << count << endl;

    return 0;
}
```

